#include "stdafx.h"#include "HcdFactory.h"KHcdFactory * KHcdFactory::pFirst = NULL;KHcdFactory * KHcdFactory::pLast = NULL;KHcdFactory::KHcdFactory( LPCSTR pType,	tfCreateNP pCreate ){  if( pFirst == NULL )    pFirst = this;  if( pLast )    pLast->pNext = this;  pLast = this;  pNext = NULL;  this->pszType = pType;  fnCreateNP = pCreate;}IHcdElement * KHcdFactory::Create( LPCSTR pType ){  for( KHcdFactory * pC = pFirst; pC; pC = pC->pNext )  {    if( _strcmpi( pType, pC->pszType ) )      continue;    IHcdElement *pB = NULL;    if( pC->fnCreateNP )      pB = (*(pC->fnCreateNP))();    if( pB )      pB->m_pszType = pC->pszType;    return pB;  }  return NULL;}